const allData = {{workflowparams:allData}};
const unique = `${allData.to_created_by || ""}_${Date.now()}`;

return {
  unique
};

const allData = {{workflowparams:allData}}

// A bundle is ONE row of table_to with the bundle's items under `children`. The
// bundle row carries the number of bundles and its items carry their own
// quantities, so both are listed -- an item under a bundle by `#parent/child`.
// A bundle whose items are all zero goes as the bundle, since fillbackHeaderFields
// drops the whole thing together.
const isBundleParent = (row) => Boolean(row.item_bundle_id) && !row.material_id;
const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

const zeroQtyArray = [];
for (const [index, to] of allData.table_to.entries()) {
  if (isBundleParent(to)) {
    const children = childrenOf(to);
    const zeroChildren = [];

    children.forEach((child, childIndex) => {
      if (child.to_qty <= 0) {
        zeroChildren.push(`#${index + 1}/${childIndex + 1}`);
      }
    });

    if (children.length === 0 || zeroChildren.length === children.length) {
      zeroQtyArray.push(`#${index + 1}`);
    } else {
      zeroQtyArray.push(...zeroChildren);
    }

    continue;
  }

  if (to.to_qty <= 0) {
    zeroQtyArray.push(`#${index + 1}`);
  }
}
let hasZero = 0
let message = null;
if (zeroQtyArray.length > 0) {
  message = `Line${zeroQtyArray.length > 1 ? "s" : ""} ${zeroQtyArray.join(
    ", ",
  )} ha${
    zeroQtyArray.length > 1 ? "ve" : "s"
  } a zero deliver quantity, which may prevent processing.\nIf you proceed, it will delete the row with 0 deliver quantity. \nWould you like to proceed?`;
  hasZero = 1
}

return {
  message,
  hasZero
};

const allData = {{workflowparams:allData}};
const tableTo = allData.table_to || [];

// A bundle is ONE row of table_to with the bundle's items under `children`. The
// bundle row holds no material, so the `row.material_id` guard below steps over
// it on its own; its items are rows in their own right and are allocated like
// any other line.
//
// rowIndex is the row's position in a flat walk of the tree. It is what the
// allocation tracker keys off to tell one row's allocation from another's, so it
// has to stay a unique whole number. parentIndex/childIndex is the address that
// writes the result back into the tree (childIndex null on a top-level row).
const rowsNeedingAllocation = [];
let flatIndex = 0;

const consider = (row, parentIndex, childIndex) => {
  const currentIndex = flatIndex;
  flatIndex += 1;

  const toQty = parseFloat(row.to_qty) || 0;
  const hasTempData = row.temp_qty_data && 
                      row.temp_qty_data !== "[]" && 
                      row.temp_qty_data.trim() !== "";

  // Only allocate if: has quantity AND no existing allocation AND has material_id
  if (toQty > 0 && !hasTempData && row.material_id) {
    rowsNeedingAllocation.push({
      rowIndex: currentIndex,
      parentIndex: parentIndex,
      childIndex: childIndex,
      materialId: row.material_id,
      quantity: toQty,
      uomId: row.to_order_uom_id,
      plantId: allData.plant_id,
      organizationId: allData.organization_id,
      soLineItemId: row.so_line_item_id || null
    });
  }
};

tableTo.forEach((row, index) => {
  consider(row, index, null);

  const children = Array.isArray(row.children) ? row.children : [];

  children.forEach((child, childIndex) => {
    consider(child, index, childIndex);
  });
});

// Initialize allocation tracker for cross-row deduplication
const allocationTracker = {};

return {
  rowsNeedingAllocation,
  allocationTracker,
  plantId: allData.plant_id,
  organizationId: allData.organization_id,
  totalRowsToAllocate: rowsNeedingAllocation.length
};

const allData = {{workflowparams:allData}};
const rowsNeedingAllocation = {{node:code_node_C58lS8pM.data.rowsNeedingAllocation}};

// Collect unique UOM IDs
const uomIds = new Set();
rowsNeedingAllocation.forEach(row => {
  if (row.uomId) uomIds.add(row.uomId);
});

return {
  uomIds: Array.from(uomIds)
};

const rowsNeedingAllocation = {{node:code_node_C58lS8pM.data.rowsNeedingAllocation}};
const currentIndexRaw = {{node:get_cache_node_aVQIWXIv.data}};
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0;

const currentRow = rowsNeedingAllocation[index];

return {
  currentRow,
  currentIndex: index,
  nextIndex: index + 1
};

// executeAllocation - Updated with pendingReservedData priority (Production first)
// ============================================================================
// INPUTS
// ============================================================================
const currentRow = {{node:code_node_cvOKI9GU.data.currentRow}};
const itemData = {{node:get_node_pxY9Jxts.data.data}};
const isBatchManaged = itemData.item_batch_management === 1;
const pickingSetup = {{node:get_node_MX4rxQLm.data.data}};
const rawTracker = {{node:get_cache_node_j89l1u3S.data}};
let allocationTracker = {};

// 🔧 NEW: Pending reserved data (fetched from search node)
const pendingReservedData = {{node:search_node_ekF4IJPz.data.data}} || [];

if (rawTracker) {
  if (typeof rawTracker === 'string') {
    try {
      allocationTracker = JSON.parse(rawTracker);
    } catch (e) {
      console.log('Failed to parse allocation tracker, using empty object');
      allocationTracker = {};
    }
  } else if (typeof rawTracker === 'object') {
    allocationTracker = rawTracker;
  }
}

// Pre-fetched data
const allUOMs = {{node:search_node_sgKuGfeN.data.data}} || [];
const allBinLocations = {{node:search_node_d34w6rCv.data.data}} || [];

// Get balance data based on batch management
let balances = [];
let batchMasterData = [];

if (isBatchManaged) {
  batchMasterData = {{node:search_node_dg4nIIRM.data.data}} || [];
  balances = {{node:search_node_ojdgySof.data.data}} || [];
} else {
  balances = {{node:search_node_54hizGno.data.data}} || [];
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

// Get default bin for this item and plant
const getDefaultBin = (itemData, plantId) => {
  if (!itemData.table_default_bin?.length) return null;
  const entry = itemData.table_default_bin.find(bin => bin.plant_id === plantId);
  return entry?.bin_location || null;
};

// Get allocations from other rows of the same material (deduplication)
const getCurrentAllocations = (materialId, currentRowIndex, tracker) => {
  const materialAllocations = tracker[materialId] || {};
  const allocatedQuantities = {};

  Object.entries(materialAllocations).forEach(([rIdx, rowAllocs]) => {
    if (parseInt(rIdx) !== currentRowIndex) {
      Object.entries(rowAllocs).forEach(([locationKey, qty]) => {
        allocatedQuantities[locationKey] = (allocatedQuantities[locationKey] || 0) + qty;
      });
    }
  });

  return allocatedQuantities;
};

// Apply cross-row deduplication to balances
const applyAllocationsToBalances = (balances, allocatedQuantities, isBatchManaged) => {
  return balances.map(balance => {
    const key = isBatchManaged
      ? `${balance.location_id}-${balance.batch_id || "no_batch"}`
      : `${balance.location_id}`;

    const allocatedFromOthers = allocatedQuantities[key] || 0;
    const originalQty = balance.unrestricted_qty || 0;
    const adjustedQty = Math.max(0, originalQty - allocatedFromOthers);

    return {
      ...balance,
      unrestricted_qty: adjustedQty,
      original_unrestricted_qty: originalQty
    };
  });
};

// Find batch master data by batch_id
const findBatchData = (batchId) => {
  if (!isBatchManaged || !batchMasterData.length) return null;
  return batchMasterData.find(b => b.id === batchId) || null;
};

// Lookup bin location from pre-fetched data
const getBinLocationDetails = (locationId) => {
  const binLocation = allBinLocations.find(bin => bin.id === locationId);
  return binLocation ? binLocation.bin_location_combine : locationId;
};

// Lookup UOM name from pre-fetched data
const getUOMName = (uomId) => {
  const uom = allUOMs.find(u => u.id === uomId);
  return uom ? uom.uom_name : "";
};

// ============================================================================
// DEDUPLICATION
// ============================================================================
const allocatedFromOtherRows = getCurrentAllocations(
  currentRow.materialId,
  currentRow.rowIndex,
  allocationTracker
);

const adjustedBalances = applyAllocationsToBalances(
  balances,
  allocatedFromOtherRows,
  isBatchManaged
);

// ============================================================================
// ALLOCATION ENGINE - STEP 0: PRIORITIZE PENDING RESERVED DATA
// ============================================================================
let allAllocations = [];
let remainingQty = currentRow.quantity;

// 🔧 NEW: Sort pending reserved data to prioritize Production over Sales Order
if (pendingReservedData.length > 0 && currentRow.soLineItemId) {
  const sortedReservedData = [...pendingReservedData].sort((a, b) => {
    if (a.doc_type === "Production" && b.doc_type !== "Production") return -1;
    if (a.doc_type !== "Production" && b.doc_type === "Production") return 1;
    return 0;
  });

  for (const reservation of sortedReservedData) {
    if (remainingQty <= 0) break;

    const reservedQty = parseFloat(reservation.open_qty || 0);
    if (reservedQty <= 0) continue;

    // Find matching balance by bin_location and batch_id (if batch-managed)
    const matchingBalance = adjustedBalances.find((b) => {
      const binMatch = b.location_id === reservation.bin_location;
      if (isBatchManaged) {
        return binMatch && b.batch_id === reservation.batch_id;
      }
      return binMatch;
    });

    if (matchingBalance) {
      const availableQty = matchingBalance.unrestricted_qty || 0;
      // Allocate min of: remaining qty, reserved qty, available balance
      const allocatedQty = Math.min(remainingQty, reservedQty, availableQty);

      if (allocatedQty > 0) {
        const binLocationName = getBinLocationDetails(matchingBalance.location_id);
        const batchData = isBatchManaged ? findBatchData(matchingBalance.batch_id) : null;

        // Check if already allocated to this location
        const existingAllocIndex = allAllocations.findIndex((a) => {
          const locMatch = a.balance.location_id === matchingBalance.location_id;
          if (isBatchManaged) {
            return locMatch && a.batchData?.id === matchingBalance.batch_id;
          }
          return locMatch;
        });

        if (existingAllocIndex >= 0) {
          allAllocations[existingAllocIndex].quantity += allocatedQty;
        } else {
          allAllocations.push({
            balance: matchingBalance,
            quantity: allocatedQty,
            binLocation: binLocationName,
            batchData: batchData,
            source: `Reserved (${reservation.doc_type})`  // For debugging
          });
        }

        remainingQty -= allocatedQty;
        // Reduce balance for next iteration
        matchingBalance.unrestricted_qty = Math.max(0, matchingBalance.unrestricted_qty - allocatedQty);
      }
    }
  }
}

// ============================================================================
// ALLOCATION ENGINE - STEP 1: APPLY STRATEGY FOR REMAINING QTY
// ============================================================================
if (remainingQty > 0) {
  const defaultBin = getDefaultBin(itemData, currentRow.plantId);
  const defaultStrategy = pickingSetup.default_strategy_id;
  const fallbackStrategy = pickingSetup.fallback_strategy_id;

  // Helper: Sort by FIFO (expired date)
  const sortByFIFO = (balanceArray) => {
    if (!isBatchManaged) return balanceArray;

    return balanceArray.sort((a, b) => {
      const batchA = findBatchData(a.batch_id);
      const batchB = findBatchData(b.batch_id);

      if (batchA?.expired_date && batchB?.expired_date) {
        return new Date(batchA.expired_date) - new Date(batchB.expired_date);
      }

      return (batchA?.batch_number || "").localeCompare(batchB?.batch_number || "");
    });
  };

  // Helper: Allocate from a list of balances
  const allocateFromBalances = (balanceList) => {
    const allocated = [];

    for (const balance of balanceList) {
      if (remainingQty <= 0) break;

      const availableQty = balance.unrestricted_qty || 0;
      if (availableQty <= 0) continue;

      const allocatedQty = Math.min(remainingQty, availableQty);

      const binLocationName = getBinLocationDetails(balance.location_id);
      const batchData = isBatchManaged ? findBatchData(balance.batch_id) : null;

      allocated.push({
        balance: balance,
        quantity: allocatedQty,
        binLocation: binLocationName,
        batchData: batchData,
        source: "Strategy"  // For debugging
      });

      remainingQty -= allocatedQty;
    }

    return allocated;
  };

  // Get already allocated location keys to exclude
  const allocatedKeys = new Set(
    allAllocations.map((a) =>
      isBatchManaged
        ? `${a.balance.location_id}-${a.batchData?.id || "no_batch"}`
        : `${a.balance.location_id}`
    )
  );

  // Filter out already allocated balances
  const remainingBalances = adjustedBalances.filter((b) => {
    const key = isBatchManaged
      ? `${b.location_id}-${b.batch_id || "no_batch"}`
      : `${b.location_id}`;
    return !allocatedKeys.has(key) && (b.unrestricted_qty || 0) > 0;
  });

  // STRATEGY: FIXED BIN
  if (defaultStrategy === "FIXED BIN") {
    // Step 1: Try default bin first (only if configured)
    if (defaultBin) {
      const defaultBinBalances = remainingBalances.filter(
        b => b.location_id === defaultBin
      );

      const sortedDefaultBalances = sortByFIFO(defaultBinBalances);
      const defaultAllocations = allocateFromBalances(sortedDefaultBalances);
      allAllocations.push(...defaultAllocations);
    }

    // Step 2: Fallback to RANDOM for remainder (or if no default bin configured)
    if (remainingQty > 0 && fallbackStrategy === "RANDOM") {
      const otherBalances = remainingBalances.filter(
        b => !defaultBin || b.location_id !== defaultBin
      );

      const sortedOtherBalances = sortByFIFO(otherBalances);
      const fallbackAllocations = allocateFromBalances(sortedOtherBalances);
      allAllocations.push(...fallbackAllocations);
    }
  }
  // STRATEGY: RANDOM
  else if (defaultStrategy === "RANDOM") {
    const sortedBalances = sortByFIFO(remainingBalances);
    const randomAllocations = allocateFromBalances(sortedBalances);
    allAllocations.push(...randomAllocations);
  }
}

// ============================================================================
// BUILD RESULTS
// ============================================================================

// Build temp_qty_data array
const tempQtyData = allAllocations.map(alloc => ({
  material_id: currentRow.materialId,
  location_id: alloc.balance.location_id,
  block_qty: alloc.balance.block_qty,
  reserved_qty: alloc.balance.reserved_qty,
  unrestricted_qty: alloc.balance.original_unrestricted_qty || alloc.balance.unrestricted_qty,
  qualityinsp_qty: alloc.balance.qualityinsp_qty,
  intransit_qty: alloc.balance.intransit_qty,
  balance_quantity: alloc.balance.balance_quantity,
  plant_id: currentRow.plantId,
  organization_id: alloc.balance.organization_id,
  is_deleted: 0,
  to_quantity: alloc.quantity,
  ...(alloc.batchData && { batch_id: alloc.batchData.id })
}));

// Get UOM name from pre-fetched data
const uomName = getUOMName(currentRow.uomId);

// Build view_stock summary
const summaryLines = allAllocations.map((alloc, idx) => {
  let line = `${idx + 1}. ${alloc.binLocation}: ${alloc.quantity} ${uomName}`;
  if (alloc.batchData) {
    line += `\n[${alloc.batchData.batch_number}]`;
  }
  return line;
});

const totalAllocated = allAllocations.reduce((sum, alloc) => sum + alloc.quantity, 0);
const viewStock = totalAllocated > 0
  ? `Total: ${totalAllocated} ${uomName}\n\nDETAILS:\n${summaryLines.join("\n")}`
  : "";

// Update allocation tracker
const updatedTracker = { ...allocationTracker };
if (!updatedTracker[currentRow.materialId]) {
  updatedTracker[currentRow.materialId] = {};
}

const rowAllocations = {};
allAllocations.forEach(alloc => {
  const key = alloc.batchData
    ? `${alloc.balance.location_id}-${alloc.batchData.id}`
    : `${alloc.balance.location_id}`;
  rowAllocations[key] = alloc.quantity;
});

updatedTracker[currentRow.materialId][currentRow.rowIndex] = rowAllocations;

// ============================================================================
// RETURN RESULTS
// ============================================================================
return {
  temp_qty_data: JSON.stringify(tempQtyData),
  view_stock: viewStock,
  total_allocated: totalAllocated,
  rowIndex: currentRow.rowIndex,
  updatedTracker: updatedTracker
};

const rawtableTO = {{node:get_cache_node_XGpEIHGk.data}};
let tableTO = [];

if (rawtableTO) {
  if (typeof rawtableTO === 'string') {
    tableTO = JSON.parse(rawtableTO);
  } else {
    tableTO = rawtableTO;
  }
}

const allocationResult = {{node:code_node_KTHlcvbv.data}};

// Where the allocated row sits. A bundle's items are rows of the tree rather
// than of table_to, so a single position cannot reach them -- prepareAllocationData
// hands over the parent's position plus the item's own, with childIndex null on
// an ordinary line.
const currentRow = {{node:code_node_cvOKI9GU.data.currentRow}} || {};
const parentIndex =
  currentRow.parentIndex !== undefined && currentRow.parentIndex !== null
    ? currentRow.parentIndex
    : allocationResult.rowIndex;
const childIndex =
  currentRow.childIndex !== undefined ? currentRow.childIndex : null;

const parentRow = tableTO[parentIndex];
let targetRow = null;

if (parentRow) {
  if (childIndex === null) {
    targetRow = parentRow;
  } else if (Array.isArray(parentRow.children)) {
    targetRow = parentRow.children[childIndex] || null;
  }
}

// Update specific row
if (targetRow) {
  targetRow.temp_qty_data = allocationResult.temp_qty_data;
  targetRow.view_stock = allocationResult.view_stock;

  const toQty = parseFloat(targetRow.to_qty) || 0;
  const initialDeliveredQty = parseFloat(targetRow.to_initial_delivered_qty) || 0;
  const orderedQty = parseFloat(targetRow.to_order_quantity) || 0;

  targetRow.to_delivered_qty = initialDeliveredQty + toQty;
  targetRow.to_undelivered_qty = orderedQty - (initialDeliveredQty + toQty);
} else {
  console.log("allocation target row not found", parentIndex, childIndex);
}

return {
  tableTO: tableTO,
  updatedTracker: allocationResult.updatedTracker
};

const allData = {{workflowparams:allData}};
const totalRowsToAllocate = {{node:code_node_C58lS8pM.data.totalRowsToAllocate}};

// If no rows were allocated, just return original table_to
if (totalRowsToAllocate === 0) {
  return { tableTO: allData.table_to };
}

// Otherwise, get the allocated table from Redis
const rawTableTo = {{node:get_cache_node_CBiQBoVP.data}};

let tableTO = [];
if (typeof rawTableTo === 'string') {
  tableTO = JSON.parse(rawTableTo);
} else {
  tableTO = rawTableTo || allData.table_to;
}

return { tableTO };

// Line ids for the reservation lookup below. An empty `equalAny` list matches
// EVERYTHING, so an empty plan sends a value that matches nothing instead --
// the same sentinel code_node_CancelPPReset uses.
const rawBefore = {{node:get_node_zG6KDDEF.data.data}};
const before = Array.isArray(rawBefore)
  ? rawBefore[0] || null
  : rawBefore || null;

const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);

const lineIds = [];
for (const row of flattenRows(before && before.table_to)) {
  if (row && row.id) lineIds.push(String(row.id));
}
if (lineIds.length === 0) lineIds.push("__none__");

const ppId = String((before && before.id) || "");

return {
  lineIds: lineIds,
  // Two shapes on purpose. `to_no` is a json array column and every working
  // filter against that shape in this repo uses `in` with a SCALAR, so that is
  // what the picking lookup gets; the array form is kept for equalAny filters.
  ppId: ppId ? [ppId] : ["__none__"],
  ppIdScalar: ppId || "__none__"
};

// Can this plan be edited now that picking has started?
//
// Ownership and mutex only. Reductions, removals and item swaps used to be refused
// here; code_pp_pick_reconcile now unwinds them instead, and owns the line statuses
// this node used to compute. What stays is what a reversal must never touch: a
// Picking mid-confirm, and a line a Goods Delivery has already taken over.
const saveAs = {{workflowparams:saveAs}};
const isPicking = {{workflowparams:isPicking}};
const allData = {{workflowparams:allData}};

const rawBefore = {{node:get_node_zG6KDDEF.data.data}};
const before = Array.isArray(rawBefore)
  ? rawBefore[0] || null
  : rawBefore || null;

const rawRes = {{node:search_node_pp_reserved.data.data}};
const reservations = Array.isArray(rawRes) ? rawRes : rawRes ? [rawRes] : [];

const rawPick = {{node:search_node_pp_pickings.data.data}};
const pickings = Array.isArray(rawPick) ? rawPick : rawPick ? [rawPick] : [];

const rawGd = {{node:search_node_pp_gd_claims.data.data}};
const gdClaims = Array.isArray(rawGd) ? rawGd : rawGd ? [rawGd] : [];

const OFF = { blockEdit: 0, blockMessage: "" };

// The Picking re-invokes this workflow with isPicking set; it must pass straight
// through, exactly as the old guard allowed.
if (saveAs !== "Created" || isPicking || !before || !allData) {
  return OFF;
}

const roundQty = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const ppId = String(before.id || "");

const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);

// Read the STORED plan, not the submitted one. A page opened before the picker
// started carries a stale picking_status.
const beforeLines = flattenRows(before.table_to).filter((r) => r && r.material_id);

const anyPicked = beforeLines.some((r) => roundQty(r.picked_qty) > 0);
const priorStatus = String(before.picking_status || "");
const started =
  priorStatus === "In Progress" || priorStatus === "Completed" || anyPicked;
const openPicking = pickings.some(
  (p) => String(p.to_status || "") === "Created"
);

if (!started && !openPicking) {
  return OFF;
}

const block = (message) => ({ blockEdit: 1, blockMessage: message });

// A Picking mid-confirm is writing these very lines from the other side. Only an
// open Picking can be mid-confirm; the flag leaks on terminal ones (8 stale rows in
// production, all Completed or Cancelled) and honouring those would lock a plan for
// good with no way to clear it.
for (const p of pickings) {
  if (String(p.to_status || "") === "Created" && Number(p.is_processing || 0) !== 0) {
    return block(
      "Picking " +
        String(p.to_id || p.id) +
        " is being processed on a device right now. Try again in a moment."
    );
  }
}

// A delivery built from this plan takes the reservation over: doc_type stays
// "Picking Plan" but target_gd_id is restamped to the delivery. Once that has
// happened the delivery also holds picking_record_id references into the pick
// records, so unwinding a pick underneath it would leave the delivery describing
// stock that no longer adds up. This is the one thing the reconcile must never do.
const claimedByLine = {};
for (const res of reservations) {
  const line = String(res.doc_line_id || "");
  if (!line) continue;
  const status = String(res.status || "");
  const target = String(res.target_gd_id || "");
  if (status === "Delivered" || (target && target !== ppId)) {
    claimedByLine[line] = 1;
  }
}

// Reservations alone are not enough. A delivery built from this plan and saved as
// Created is a deliberate no-inventory middle state -- code_node_b71wypDJ returns
// early and writes no reservation row at all -- so its claim is invisible above
// while it holds picking_record_id references into the pick records. The delivery
// line itself is the only evidence.
for (const g of gdClaims) {
  const line = String(g.pp_line_item_id || "");
  if (line) claimedByLine[line] = 1;
}

for (const line of beforeLines) {
  const id = String(line.id || "");
  if (!id) continue;
  if (roundQty(line.picked_qty) > 0 && claimedByLine[id]) {
    return block(
      "Item " +
        (line.material_name || line.to_material_desc || id) +
        " has already been taken by a Goods Delivery, so this plan can no longer be changed. Revert and cancel that delivery first."
    );
  }
}

return { blockEdit: 0, blockMessage: "" };

// Picking reconcile for a Picking Plan -- planning pass.
//
// A delivery reconciles its Picking in place; a plan used to refuse instead. This
// classifies each plan line against the Picking as it stands so the producer can
// merge rather than rebuild, and unwinds what was over-picked. Nothing is written
// here: the confirm returns before the first update node.
//
// Ported from GDheadWorkflow's code_pick_reconcile, with three PP differences:
//   - keys are to_id / to_line_id, never gd_id / gd_line_id
//   - handling_unit_id is NOT part of any key: PP pick records always carry null
//     (code_node_Q3hWck9R writes item.handling_unit_id and PP picking rows never
//     set it), so a key including it would match nothing
//   - qty_to_pick on a PP picking row means "remaining at conversion", not the whole
//     line, so the producer keeps qty_to_pick - pending_process_qty === picked
const saveAs = {{workflowparams:saveAs}};
const isPicking = {{workflowparams:isPicking}};
const confirmReversal = {{workflowparams:confirmPickReversal}};
const allData = {{workflowparams:allData}};

const rawBefore = {{node:get_node_zG6KDDEF.data.data}};
const before = Array.isArray(rawBefore) ? rawBefore[0] || null : rawBefore || null;

const rawPick = {{node:search_node_pp_pickings.data.data}};
const pickings = Array.isArray(rawPick) ? rawPick : rawPick ? [rawPick] : [];

const OFF = {
  reconcileNeeded: 0,
  blockEdit: 0,
  blockMessage: "",
  pickingId: "",
  pickingNo: "",
  targetPickingToStatus: "",
  linePlans: [],
  lineStatusOverrides: {},
  lineFieldOverrides: {},
  headerPickingStatus: "",
  hasReversals: 0,
  needsReversalConfirm: 0,
  reversals: [],
  binIdsToName: ["0"],
  batchIdsToName: ["0"],
  recordAdjustments: [],
  reversalNote: ""
};

// The Picking re-invokes this workflow with isPicking set; it must pass straight
// through, exactly as code_node_pp_gate allows.
if (saveAs !== "Created" || isPicking || !before || !allData) {
  return OFF;
}

const roundQty = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const sid = (v) => String(v === null || v === undefined ? "" : v);
const ppId = sid(before.id);

const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);
const parseAlloc = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
};
// picked_temp_qty_data is keyed on where the stock ENDED UP, which is what
// code_node_AGoxWP7x writes and what PPconvertToPicking subtracts against.
const allocKey = (e) =>
  sid(e.location_id) + "|" + sid(e.batch_id) + "|" + sid(e.handling_unit_id);

const beforeLines = flattenRows(before.table_to).filter((r) => r && r.material_id);
const afterLines = flattenRows(allData.table_to).filter((r) => r && r.material_id);
const afterById = {};
for (const row of afterLines) {
  if (row.id) afterById[sid(row.id)] = row;
}
const beforeById = {};
for (const row of beforeLines) {
  if (row.id) beforeById[sid(row.id)] = row;
}

const anyPicked = beforeLines.some((r) => roundQty(r.picked_qty) > 0);
const priorStatus = sid(before.picking_status);
const started =
  priorStatus === "In Progress" || priorStatus === "Completed" || anyPicked;
const openPicking = pickings.some((p) => sid(p.to_status) === "Created");
if (!started && !openPicking) {
  return OFF;
}

const blockWith = (message) =>
  Object.assign({}, OFF, { blockEdit: 1, blockMessage: message });

// --- which lines this edit actually touches --------------------------------
// Only these decide which Picking is in scope, so an unrelated line on a second
// Picking never drags the whole plan into a refusal.
const affected = {};
for (const line of beforeLines) {
  const id = sid(line.id);
  if (!id) continue;
  const after = afterById[id];
  if (!after) {
    affected[id] = 1;
    continue;
  }
  if (sid(after.material_id) !== sid(line.material_id)) {
    affected[id] = 1;
    continue;
  }
  if (Math.abs(roundQty(after.to_qty) - roundQty(line.to_qty)) > 0.0005) {
    affected[id] = 1;
    continue;
  }
  // A re-allocation at the SAME quantity still matters. PPconvertToPicking works
  // out what is left to pick by subtracting picked_temp_qty_data from
  // temp_qty_data key by key, so a picked bin the plan no longer allocates comes
  // back as quantity to pick a second time. The gate this replaces checked every
  // picked line for that; testing quantity and material alone would have let it
  // through. Only broken COVERAGE counts -- a reshuffle that still covers what
  // was picked changes nothing anyone downstream reads.
  const pickedHere = {};
  for (const entry of parseAlloc(line.picked_temp_qty_data)) {
    const q = roundQty(entry.to_quantity);
    if (q > 0) {
      const k = allocKey(entry);
      pickedHere[k] = roundQty((pickedHere[k] || 0) + q);
    }
  }
  const pickedKeys = Object.keys(pickedHere);
  if (!pickedKeys.length) continue;
  const plannedHere = {};
  for (const entry of parseAlloc(after.temp_qty_data)) {
    const q = roundQty(entry.to_quantity);
    if (q > 0) {
      const k = allocKey(entry);
      plannedHere[k] = roundQty((plannedHere[k] || 0) + q);
    }
  }
  if (pickedKeys.some((k) => roundQty(plannedHere[k]) < pickedHere[k])) {
    affected[id] = 1;
  }
}
const affectedIds = Object.keys(affected);
if (affectedIds.length === 0) {
  return OFF;
}

// --- pick the Picking ------------------------------------------------------
// A plan legitimately owns several Pickings: each closes wholesale and the
// remainder converts again. Reconciling across them would hand one Picking the
// quantity another still plans to pick, so more than one holding an affected line
// is refused. Rows, not just records -- an unpicked-but-planned row is just as
// much a claim.
const rowsOf = (p) =>
  flattenRows(p.table_picking_items).filter((r) => r && r.row_type !== "header");
const holders = pickings.filter((p) =>
  rowsOf(p).some((r) => affected[sid(r.to_line_id)])
);
if (holders.length === 0) {
  return OFF;
}
if (holders.length > 1) {
  return blockWith(
    "This change affects lines that are split across " +
      holders.length +
      " Pickings (" +
      holders.map((p) => sid(p.to_id || p.id)).join(", ") +
      "). Cancel or revert all but one before changing the plan."
  );
}
const picking = holders[0];
const pickingNo = sid(picking.to_id || picking.id);

// A Picking mid-confirm is writing these very rows from the other side.
if (sid(picking.to_status) === "Created" && Number(picking.is_processing || 0) !== 0) {
  return blockWith(
    "Picking " + pickingNo + " is being processed on a device right now. Try again in a moment."
  );
}

// --- the Picking as it stands ----------------------------------------------
const allPlanRows = rowsOf(picking);
const planRows = allPlanRows.filter((r) => sid(r.to_id) === ppId);
const otherRows = allPlanRows.filter((r) => sid(r.to_id) !== ppId);
const records = (picking.table_picking_records || []).filter(
  (r) => r && sid(r.to_id) === ppId
);

const slotKey = (line, item) => sid(line) + "|" + sid(item);
const slots = {};
const slotFor = (line, item) => {
  const k = slotKey(line, item);
  if (!slots[k]) {
    slots[k] = { key: k, line: sid(line), item: sid(item), picked: 0, planned: 0, pending: 0, desired: 0 };
  }
  return slots[k];
};

// Records are the authority on what was physically picked.
const pickedSeen = {};
for (const rec of records) {
  const q = parseFloat(rec.store_out_qty) || 0;
  if (!rec.to_line_id || q <= 0) continue;
  const s = slotFor(rec.to_line_id, rec.item_code);
  s.picked = roundQty(s.picked + q);
  pickedSeen[s.key] = 1;
}
// A force-completed Picking writes no records; fall back to the plan's arithmetic.
for (const row of planRows) {
  if (!row.to_line_id) continue;
  const s = slotFor(row.to_line_id, row.item_code);
  if (pickedSeen[s.key]) continue;
  const done = roundQty(
    (parseFloat(row.qty_to_pick) || 0) - (parseFloat(row.pending_process_qty) || 0)
  );
  if (done > 0) s.picked = roundQty(s.picked + done);
}
for (const row of planRows) {
  if (!row.to_line_id || row.line_status === "Cancelled") continue;
  const s = slotFor(row.to_line_id, row.item_code);
  s.planned = roundQty(s.planned + (parseFloat(row.qty_to_pick) || 0));
  s.pending = roundQty(s.pending + (parseFloat(row.pending_process_qty) || 0));
}

// --- what the plan now wants -----------------------------------------------
// Keyed by the row's CURRENT material, so an item swap decomposes into a full
// reversal of the old item plus a fresh Open row for the new one. to_qty is the
// authority: code_node_Nj60Z2XF already refuses a temp_qty_data that disagrees.
for (const row of afterLines) {
  const line = sid(row.id);
  if (!line) continue;
  const s = slotFor(line, row.material_id);
  s.desired = roundQty(s.desired + roundQty(row.to_qty));
}

// --- classify ---------------------------------------------------------------
const linePlans = [];
const shortfalls = [];
const survivingByLine = {};
for (const k of Object.keys(slots)) {
  const s = slots[k];
  if (s.desired < s.picked) {
    shortfalls.push(s);
    continue;
  }
  const newPending = roundQty(Math.max(0, s.desired - s.picked));
  linePlans.push({
    to_line_id: s.line,
    item_code: s.item,
    mode: s.picked === 0 ? "rebuild" : s.desired > s.planned ? "extend" : s.desired < s.planned ? "shrink" : "hold",
    picked: s.picked, planned: s.planned, pending: s.pending, desired: s.desired,
    newPending: newPending
  });
  if (s.desired > 0) {
    if (!survivingByLine[s.line]) survivingByLine[s.line] = { done: true, progress: false };
    if (newPending > 0) survivingByLine[s.line].done = false;
    if (s.picked > 0) survivingByLine[s.line].progress = true;
  }
}

// --- unwind what was over-picked -------------------------------------------
const recordsBySlot = {};
for (const rec of records) {
  if (!rec.to_line_id) continue;
  const k = slotKey(rec.to_line_id, rec.item_code);
  if (!recordsBySlot[k]) recordsBySlot[k] = [];
  recordsBySlot[k].push(rec);
}

// Serialised lines cannot be unwound: the records do not say WHICH serial was taken.
const serialisedSlots = {};
for (const row of planRows) {
  const isSerial =
    Number(row.is_serialized_item || 0) === 1 ||
    (row.serial_numbers !== undefined && row.serial_numbers !== null && sid(row.serial_numbers) !== "");
  if (isSerial) serialisedSlots[slotKey(row.to_line_id, row.item_code)] = 1;
}
const serialShortfall = shortfalls.filter((s) => serialisedSlots[s.key]);
if (serialShortfall.length > 0) {
  return blockWith(
    "Reducing " + serialShortfall.length + " serialised line(s) on " + pickingNo +
      " cannot be reversed automatically, because the pick records do not record which serial numbers were taken. Cancel the Picking first."
  );
}

const reversals = [];
const recordAdjustments = [];
const binIdSet = {};
const batchIdSet = {};
// take-back per (line, picked_temp_qty_data key), so picked_temp_qty_data can be
// reduced in exactly the places the records came from.
const takenByLineKey = {};

for (const s of shortfalls) {
  let left = roundQty(s.picked - s.desired);
  const newestFirst = (recordsBySlot[s.key] || []).slice().sort((a, b) => {
    const ta = sid(a.confirmed_at);
    const tb = sid(b.confirmed_at);
    if (ta !== tb) return ta < tb ? 1 : -1;
    return sid(a.id) < sid(b.id) ? 1 : -1;
  });

  for (const rec of newestFirst) {
    if (left <= 0) break;
    const have = roundQty(rec.store_out_qty);
    if (have <= 0) continue;

    // A delivery has already consumed this pick; unwinding it would leave the
    // delivery describing stock that no longer adds up.
    if (roundQty(rec.delivered_qty) > 0) {
      return blockWith(
        "Item " + sid(rec.item_name || rec.item_code) + " on " + pickingNo +
          " has already been delivered, so the picked quantity cannot be reversed. Revert that delivery first."
      );
    }

    const take = roundQty(Math.min(left, have));
    const remain = roundQty(have - take);
    const alt = roundQty(rec.picked_qty_alt);
    const newAlt = have > 0 ? roundQty(alt * (remain / have)) : 0;

    recordAdjustments.push({
      id: sid(rec.id),
      store_out_qty: remain,
      picked_qty_alt: newAlt,
      drop: remain <= 0 ? 1 : 0,
      qty: take
    });
    reversals.push({
      to_line_id: s.line,
      item_code: sid(rec.item_code),
      item_name: sid(rec.item_name),
      qty: take,
      return_to: sid(rec.source_bin),
      currently_at: sid(rec.target_location || rec.source_bin)
    });

    // The key picked_temp_qty_data used when this record was written.
    const k = s.line + "||" + allocKey({
      location_id: rec.target_location || rec.source_bin,
      batch_id: rec.target_batch || rec.batch_no,
      handling_unit_id: rec.handling_unit_id
    });
    takenByLineKey[k] = roundQty((takenByLineKey[k] || 0) + take);

    if (rec.source_bin) binIdSet[sid(rec.source_bin)] = 1;
    if (rec.target_location) binIdSet[sid(rec.target_location)] = 1;
    if (rec.batch_no) batchIdSet[sid(rec.batch_no)] = 1;
    if (rec.target_batch) batchIdSet[sid(rec.target_batch)] = 1;
    left = roundQty(left - take);
  }

  if (left > 0) {
    return blockWith(
      "Line " + s.line + " on " + pickingNo + " shows " + s.picked +
        " picked but has no pick records covering " + left +
        " of it (a force-completed Picking records none), so it cannot be reversed automatically. Cancel the Picking first."
    );
  }

  linePlans.push({
    to_line_id: s.line, item_code: s.item, mode: "reverse",
    picked: s.desired, planned: s.planned, pending: s.pending,
    desired: s.desired, newPending: 0
  });
  if (s.desired > 0) {
    if (!survivingByLine[s.line]) survivingByLine[s.line] = { done: true, progress: true };
    survivingByLine[s.line].progress = true;
  }
}

// --- rebuild each touched line's picked state -------------------------------
const lineFieldOverrides = {};
const pickedAfterByLine = {};
for (const k of Object.keys(slots)) {
  const line = slots[k].line;
  if (!line || pickedAfterByLine[line] !== undefined) continue;
  const stored = beforeById[line];
  if (!stored) continue;

  const entries = parseAlloc(stored.picked_temp_qty_data)
    .map((e) => Object.assign({}, e))
    .filter((e) => roundQty(e.to_quantity) > 0);
  for (const e of entries) {
    const take = takenByLineKey[line + "||" + allocKey(e)] || 0;
    if (take > 0) e.to_quantity = roundQty(Math.max(0, roundQty(e.to_quantity) - take));
  }
  const kept = entries.filter((e) => roundQty(e.to_quantity) > 0);
  const pickedNow = roundQty(kept.reduce((sum, e) => sum + roundQty(e.to_quantity), 0));
  pickedAfterByLine[line] = pickedNow;

  // picked_view_stock needs display names, which a code-node cannot fetch --
  // code_pp_reversal_msg renders it once the name lookups have run.
  lineFieldOverrides[line] = {
    picked_qty: pickedNow,
    picked_temp_qty_data: JSON.stringify(kept)
  };
  for (const e of kept) {
    if (e.location_id) binIdSet[sid(e.location_id)] = 1;
    if (e.batch_id) batchIdSet[sid(e.batch_id)] = 1;
  }
}

// --- the old refusal 6, now evaluated AFTER the unwind ----------------------
// A key dropped from temp_qty_data comes back as quantity to pick a second time
// (PPconvertToPicking subtracts key by key). Checking post-unwind means reducing
// and re-allocating in one edit is no longer refused.
for (const line of Object.keys(lineFieldOverrides)) {
  const after = afterById[line];
  if (!after) continue;
  const pickedBy = {};
  for (const e of parseAlloc(lineFieldOverrides[line].picked_temp_qty_data)) {
    const q = roundQty(e.to_quantity);
    if (q > 0) pickedBy[allocKey(e)] = roundQty((pickedBy[allocKey(e)] || 0) + q);
  }
  const keys = Object.keys(pickedBy);
  if (!keys.length) continue;
  const plannedBy = {};
  for (const e of parseAlloc(after.temp_qty_data)) {
    const q = roundQty(e.to_quantity);
    if (q > 0) plannedBy[allocKey(e)] = roundQty((plannedBy[allocKey(e)] || 0) + q);
  }
  const stored = beforeById[line] || {};
  const label = stored.material_name || stored.to_material_desc || line;
  for (const key of keys) {
    if (roundQty(plannedBy[key]) < pickedBy[key]) {
      return blockWith(
        "Item " + label + " has " + pickedBy[key] +
          " already picked from a bin and batch the plan no longer allocates. Allocate that quantity back to the same bin, or cancel or revert Picking " +
          pickingNo + " first."
      );
    }
  }
}

// --- statuses ---------------------------------------------------------------
const lineStatusOverrides = {};
const touchedLines = {};
for (const k of Object.keys(slots)) touchedLines[slots[k].line] = 1;
for (const line of Object.keys(touchedLines)) {
  const stored = beforeById[line];
  // A line delivered straight to a Goods Delivery without ever being picked reads
  // Completed with nothing picked; recomputing would re-offer it for picking.
  if (stored && roundQty(stored.picked_qty) === 0 && sid(stored.picking_status) === "Completed") {
    continue;
  }
  const surv = survivingByLine[line];
  if (!surv) lineStatusOverrides[line] = "Cancelled";
  else if (surv.done) lineStatusOverrides[line] = "Completed";
  else if (surv.progress) lineStatusOverrides[line] = "In Progress";
  else lineStatusOverrides[line] = "Created";
  if (lineFieldOverrides[line]) {
    lineFieldOverrides[line].picking_status = lineStatusOverrides[line];
  }
}

const binIdsToName = Object.keys(binIdSet);
if (binIdsToName.length === 0) binIdsToName.push("0");
const batchIdsToName = Object.keys(batchIdSet);
if (batchIdsToName.length === 0) batchIdsToName.push("0");

const reversalNote = reversals
  .map((r) => (r.item_name || r.item_code) + ": return " + r.qty +
    (r.currently_at && r.currently_at !== r.return_to ? " (currently staged away from its source bin)" : ""))
  .join("; ");

// --- roll the statuses up ---------------------------------------------------
let allDone = true, anyProgress = false, anyLive = false;
let ppAllDone = true, ppAnyProgress = false, ppAnyLive = false;
for (const p of linePlans) {
  if (p.desired === 0) continue;
  anyLive = true; ppAnyLive = true;
  if (p.newPending > 0) { allDone = false; ppAllDone = false; }
  if (p.picked > 0) { anyProgress = true; ppAnyProgress = true; }
}
for (const row of otherRows) {
  if (row.line_status === "Cancelled") continue;
  anyLive = true;
  if ((parseFloat(row.pending_process_qty) || 0) > 0) allDone = false;
  if (row.line_status === "Completed" || row.line_status === "In Progress") anyProgress = true;
}
const rollup = (live, done, progress) =>
  !live ? "Created" : done ? "Completed" : progress ? "In Progress" : "Created";

return {
  reconcileNeeded: 1,
  blockEdit: 0,
  blockMessage: "",
  pickingId: sid(picking.id),
  pickingNo: pickingNo,
  targetPickingToStatus: rollup(anyLive, allDone, anyProgress),
  linePlans: linePlans,
  lineStatusOverrides: lineStatusOverrides,
  lineFieldOverrides: lineFieldOverrides,
  headerPickingStatus: rollup(ppAnyLive, ppAllDone, ppAnyProgress),
  hasReversals: reversals.length > 0 ? 1 : 0,
  needsReversalConfirm: reversals.length > 0 && confirmReversal !== "Yes" ? 1 : 0,
  reversals: reversals,
  binIdsToName: binIdsToName,
  batchIdsToName: batchIdsToName,
  recordAdjustments: recordAdjustments,
  reversalNote: reversalNote
};

// Turn the reversal plan into something an operator can act on, and finish the line
// overrides the reconcile could not: picked_view_stock is a rendered summary of bin
// and batch NAMES, and a code-node cannot fetch those. This node runs after the name
// lookups and only when there is something to reverse.
const reversals = {{node:code_pp_pick_reconcile.data.reversals}} || [];
const pickingNo = {{node:code_pp_pick_reconcile.data.pickingNo}} || "";
const overrides = {{node:code_pp_pick_reconcile.data.lineFieldOverrides}} || {};
const allData = {{workflowparams:allData}};

const rawBins = {{node:search_pp_rev_bins.data.data}};
const bins = Array.isArray(rawBins) ? rawBins : rawBins ? [rawBins] : [];
const rawBatches = {{node:search_pp_rev_batches.data.data}};
const batches = Array.isArray(rawBatches) ? rawBatches : rawBatches ? [rawBatches] : [];

const sid = (v) => String(v === null || v === undefined ? "" : v);
const round3 = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;

const binName = {};
for (const b of bins) {
  if (b && b.id) binName[sid(b.id)] = b.bin_location_combine || b.bin_name || sid(b.id);
}
const batchName = {};
for (const b of batches) {
  if (b && b.id) batchName[sid(b.id)] = b.batch_number || sid(b.id);
}
const label = (id) => binName[sid(id)] || sid(id) || "its source bin";
const batchLabel = (id) => batchName[sid(id)] || sid(id);

// --- the operator-facing message -------------------------------------------
// Merge by item and bin pair so one line does not produce a wall of near-identical
// bullets when several scans are unwound.
const merged = {};
for (const r of reversals) {
  const key = r.item_code + "|" + r.return_to + "|" + r.currently_at;
  if (!merged[key]) merged[key] = Object.assign({}, r, { qty: 0 });
  merged[key].qty = round3(merged[key].qty + (parseFloat(r.qty) || 0));
}

const lines = Object.keys(merged).map((k) => {
  const r = merged[k];
  const what = r.item_name || r.item_code;
  // Where the pick moved the stock (a loading bay) the two bins differ, and saying
  // so is the difference between a paper correction and a physical one. The released
  // quantity is recorded as unrestricted where it currently sits, not where it came
  // from, so carrying it back needs a Stock Movement to stay honest.
  if (r.currently_at && r.currently_at !== r.return_to) {
    return (
      "• " + what + ": " + r.qty + " is staged at " + label(r.currently_at) +
      " — move it back to " + label(r.return_to) + " and record it with a Stock Movement"
    );
  }
  return (
    "• " + what + ": " + r.qty + " picked at " + label(r.return_to) +
    " will be released (no physical move needed)"
  );
});

const body = lines.join("\n");

// --- picked_view_stock, rendered the way code_node_AGoxWP7x does ------------
const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : [])
  ]);
const lineById = {};
for (const row of flattenRows(allData && allData.table_to)) {
  if (row && row.id) lineById[sid(row.id)] = row;
}
// The UOM is already spelled out in whatever summary the line carries; reading it
// back avoids a lookup that would tell us nothing new.
const uomOf = (row) => {
  const m = /Total:\s*[\d.]+\s+(\S+)/.exec(
    sid((row && row.picked_view_stock) || (row && row.view_stock) || "")
  );
  return m ? m[1] : sid(row && row.to_uom_id) || "PCS";
};
const buildViewStock = (entries, uom) => {
  const list = Array.isArray(entries) ? entries : [];
  const total = round3(list.reduce((s, e) => s + round3(e.to_quantity), 0));
  if (total <= 0) return "";
  let out = "Total: " + total + " " + uom + "\n\nDETAILS:\n";
  list.forEach((e, i) => {
    out += (i + 1) + ". " + label(e.location_id) + ": " + round3(e.to_quantity) + " " + uom;
