// A bundle is ONE row with its items under `children` -- the same shape the source
// document is stored in, and the same one the platform reads back. Nesting the
// items rather than laying them out beside the bundle keeps the two together
// whatever else reorders the table, and keeps the items out of the handling-unit
// grouping, which only ever walks top-level rows.
const nestBundleRows = (rows) => {
  const nested = [];
  const bundleRowByLineId = new Map();

  for (const row of rows) {
    const parentLineId = row.bundle_parent_line_id;
    delete row.bundle_parent_line_id;

    if (!parentLineId) {
      // The bundle row itself, keyed by the source line its items point back at.
      // It is the only row carrying a bundle id but no item.
      if (row.item_bundle_id && !row.item_code) {
        bundleRowByLineId.set(String(row.gd_line_id || row.to_line_id || ""), row);
      }

      nested.push(row);
      continue;
    }

    const parentRow = bundleRowByLineId.get(String(parentLineId));

    // A bundle row is only created when its bundle still has something to pick.
    // An item whose bundle row was never created stays a row of its own rather
    // than being dropped from the picking altogether.
    if (!parentRow) {
      nested.push(row);
      continue;
    }

    if (!Array.isArray(parentRow.children)) parentRow.children = [];
    parentRow.children.push({ ...row, row_type: "item" });
  }

  return nested;
};

const parseJsonSafely = (jsonString, defaultValue = []) => {
  try {
    return jsonString ? JSON.parse(jsonString) : defaultValue;
  } catch (error) {
    console.error("JSON parse error:", error);
    return defaultValue;
  }
};

const allData = {{node:code_node_l5Y5WSQG.data.toData}};
const pageStatus = {{workflowparams:pageStatus}};
const ppId = allData.id
const pickingNoType = {{node:get_node_QQZAg4u9.data.data.id}};
const organizationId = allData.organization_id;

const reconcilePlan = {{node:code_pp_pick_reconcile.data}} || {};

// The Picking, not the plan. This used to read get_node_zG6KDDEF -- the plan's own
// record -- so update_node_sLiANU7B filtered Picking.id against a plan id and
// matched nothing: every edit silently left the Picking alone. Resolved out of the
// same snapshot the reconcile classified against, because a fresh read could hold
// rows the record adjustments no longer describe.
const rawPickings = {{node:search_node_pp_pickings.data.data}};
const pickings = Array.isArray(rawPickings)
  ? rawPickings
  : rawPickings
    ? [rawPickings]
    : [];
const targetPickingId = String(reconcilePlan.pickingId || "");
const existingTOData =
  (targetPickingId
    ? pickings.find((p) => String(p.id) === targetPickingId)
    : pickings.find((p) => String(p.to_status || "") === "Created")) || null;
// An edit never CREATES a Picking from here. A plan whose only Picking has closed
// converts its remainder as a second one -- that is PPconvertToPicking's job, and
// minting one here would leave the plan owning two. isUpdate stays 1 with a null
// id, so the update node matches nothing, exactly how this path behaved before the
// id it filters on was corrected.
const isUpdate = existingTOData ? 1 : pageStatus === "Add" ? 0 : 1;
const existingTO = existingTOData || null;

// Process table items with grouping for serialized items
const pickingItemGroups = new Map();

// A bundle is ONE row of table_to with the bundle's items under `children`. The
// bundle row holds no material and nothing is picked against it -- the
// `item.material_id` guard below steps over it -- while its items are picked
// like any other line, so the tree is walked flat. A document stored without
// nesting passes through unchanged.
const flattenRows = (rows) =>
  (rows || []).flatMap((row) => [
    row,
    ...(Array.isArray(row.children) ? row.children : []),
  ]);

// A bundle's items each carry item_bundle_id, but only the bundle row carries the
// bundle's number (its material_name is the ib_no) -- and that row never becomes a
// picking line, because nothing is picked against a bundle. The number is read off
// it here so every component line can show which bundle it belongs to, which is what
// lets the picker see that their quantities are locked together.
const bundleNoById = {};
// The bundle rows themselves, kept whole: the bundle row is a picking line in its
// own right -- it is the one the picker types on.
const bundleRowById = {};
for (const row of allData.table_to || []) {
  if (row && row.item_bundle_id && !row.material_id) {
    bundleNoById[String(row.item_bundle_id)] = row.material_name || "";
    if (row.id != null) bundleRowById[String(row.id)] = row;
  }
}

// Which bundle row each item hangs off. The same bundle can appear twice on one
// document, and the all-or-nothing check has to judge each occurrence on its own --
// grouping by the bundle alone would merge them and reject a picker who legitimately
// completed one and left the other. Both shapes are read: nested under `children`
// before the document is stored, flat through parent_id afterwards.
const bundleParentByLineId = {};
for (const row of allData.table_to || []) {
  if (!row) continue;
  for (const kid of Array.isArray(row.children) ? row.children : []) {
    if (kid && kid.id != null) bundleParentByLineId[String(kid.id)] = String(row.id);
  }
  if (row.parent_id != null && row.parent_id !== "" && row.id != null) {
    bundleParentByLineId[String(row.id)] = String(row.parent_id);
  }
}

flattenRows(allData.table_to).forEach((item, toLineIndex) => {
  // The bundle row itself, created the moment its first item appears so it lands
  // directly above them. It holds no stock -- no material, no bin, no batch, no
  // handling unit -- but it IS the line the picker works on: its quantity is the
  // number of bundles, and every item under it follows from that by ratio. Only
  // bundles that still have something to pick get one, which is why it is created
  // from the surviving items rather than from the source rows.
  const parentLineId = item.item_bundle_id
    ? bundleParentByLineId[String(item.id)]
    : null;
  if (parentLineId && !pickingItemGroups.has(`bundle_${parentLineId}`)) {
    const bundleRow = bundleRowById[String(parentLineId)];
    if (bundleRow) {
      pickingItemGroups.set(`bundle_${parentLineId}`, {
        item_bundle_id: bundleRow.item_bundle_id || null,
        bundle_parent_line_id: null,
        item_code: "",
        item_name: bundleRow.material_name || "",
        item_desc: bundleRow.to_material_desc || "",
        more_desc: bundleRow.more_desc || "",
        batch_no: null,
        qty_to_pick: parseFloat(bundleRow.to_qty) || 0,
        item_uom: "",
        source_bin: "",
        pending_process_qty: parseFloat(bundleRow.to_qty) || 0,
        line_status: "Open",
        so_no: bundleRow.line_so_no,
        to_no: allData.to_no,
        so_id: String(bundleRow.line_so_id || ""),
        so_line_id: String(bundleRow.so_line_item_id || ""),
        to_id: ppId,
        to_line_id: String(bundleRow.id),
        serial_numbers: [],
        is_serialized_item: 0,
      });
    }
  }

  if (item.temp_qty_data && item.material_id) {
    try {
      const tempData = parseJsonSafely(item.temp_qty_data);

      tempData.forEach((tempItem) => {
        const materialId = tempItem.material_id || item.material_id;
        // Create a grouping key based on item, batch, location, and TO line index to prevent merging separate lines
        const groupKey = `${materialId}_${tempItem.batch_id || "no-batch"}_${tempItem.location_id}_line${toLineIndex}`;

        if (!pickingItemGroups.has(groupKey)) {
          // Create new group
          pickingItemGroups.set(groupKey, {
            item_bundle_id: item.item_bundle_id || null,
            bundle_parent_line_id: item.item_bundle_id
              ? bundleParentByLineId[String(item.id)] || null
              : null,
            item_code: String(materialId),
            item_name: item.material_name,
            item_desc: item.to_material_desc || "",
            more_desc: item.more_desc || "",
            batch_no: tempItem.batch_id ? String(tempItem.batch_id) : null,
            item_batch_id: tempItem.batch_id ? String(tempItem.batch_id) : null,
            qty_to_pick: 0,
            item_uom: String(item.to_order_uom_id),
            pending_process_qty: 0,
            source_bin: String(tempItem.location_id),
            line_status: "Open",
            so_no: item.line_so_no,
            to_no: allData.to_no,
            so_id: item.line_so_id,
            so_line_id: item.so_line_item_id,
            to_id: ppId,
            to_line_id: item.id,
            serial_numbers: [],
          });
        }

        const group = pickingItemGroups.get(groupKey);
        group.qty_to_pick += parseFloat(tempItem.to_quantity);
        group.pending_process_qty += parseFloat(tempItem.to_quantity);

        // Add serial number if exists
        if (tempItem.serial_number) {
          group.serial_numbers.push(String(tempItem.serial_number));
        }
      });
    } catch (error) {
      console.error(`Error parsing temp_qty_data: ${error.message}`);
    }
  }
});

// Convert grouped items to picking items array
const tablePickingItems = [];
pickingItemGroups.forEach((group) => {
  // Format serial numbers with comma if any exist
  if (group.serial_numbers.length > 0) {
    group.serial_numbers = group.serial_numbers.join(", ");
    group.is_serialized_item = 1;
  } else {
    delete group.serial_numbers;
    group.is_serialized_item = 0;
  }
  tablePickingItems.push(group);
});

// --- merge into the Picking that already exists ---------------------------
// Handing back a freshly built array soft-deletes every plan row and re-inserts it
// under a new id, which detaches whatever the picker has open. Merge instead:
//   rows belonging to other plans are carried through verbatim -- one Picking can
//     cover several;
//   this plan's rows keep their id wherever the line/item/batch/bin key survives;
//   rows with no counterpart are simply not emitted, which the platform soft-deletes;
//   quantity already picked on a line is spread over the rows the plan now wants,
//     so only the remainder is left open.
const flattenPlanRows = (rows) =>
  (rows || []).flatMap((r) => [
    r,
    ...(Array.isArray(r.children) ? r.children : [])
  ]);

const storedRows = flattenPlanRows(
  existingTOData && existingTOData.table_picking_items
).filter((r) => r && r.row_type !== "header");

const carriedRows = storedRows.filter(
  (r) => String(r.to_id || "") !== String(ppId)
);

// No handling unit in the key: PP pick rows never set one, so including it would
// stop every row matching its stored counterpart.
const planKeyOf = (r) =>
  [
    String(r.to_line_id || ""),
    String(r.item_code || ""),
    String(r.batch_no || ""),
    String(r.source_bin || "")
  ].join("|");

const storedByKey = {};
for (const r of storedRows) {
  if (String(r.to_id || "") !== String(ppId)) continue;
  const k = planKeyOf(r);
  if (!storedByKey[k]) storedByKey[k] = r;
}

// Keyed by line AND item: a line whose item was swapped carries two plans, and the
// old item's picked quantity must not be handed to the new one.
const pickedLeft = {};
for (const lp of reconcilePlan.linePlans || []) {
  const k = String(lp.to_line_id || "") + "|" + String(lp.item_code || "");
  pickedLeft[k] = parseFloat(lp.picked) || 0;
}
// The reconcile only runs when the edit actually touches a picked line. On an
// auto_trigger_to org every other edit reaches this node with no plan at all, and
// rebuilding from temp_qty_data alone would reset the picker's progress to Open --
// so read it back off the stored rows instead.
if (!(reconcilePlan.linePlans || []).length) {
  for (const r of storedRows) {
    if (String(r.to_id || "") !== String(ppId)) continue;
    if (r.line_status === "Cancelled") continue;
    const k = String(r.to_line_id || "") + "|" + String(r.item_code || "");
    const done =
      (parseFloat(r.qty_to_pick) || 0) - (parseFloat(r.pending_process_qty) || 0);
    if (done > 0) pickedLeft[k] = Math.round(((pickedLeft[k] || 0) + done) * 1000) / 1000;
  }
}

// Rows that already carry progress get first claim on their line's picked quantity,
// so a row whose bin is unchanged keeps its status rather than the progress landing
// on a sibling row the picker never touched.
const progressOf = (r) => {
  const s = storedByKey[planKeyOf(r)];
  if (!s) return 0;
  return Math.max(
    0,
    (parseFloat(s.qty_to_pick) || 0) - (parseFloat(s.pending_process_qty) || 0)
  );
};

const claimOrder = tablePickingItems
  .slice()
  .sort((a, b) => progressOf(b) - progressOf(a));

for (const row of claimOrder) {
  const stored = storedByKey[planKeyOf(row)];
  if (stored && stored.id) row.id = stored.id;

  const slot = String(row.to_line_id || "") + "|" + String(row.item_code || "");
  const want = parseFloat(row.qty_to_pick) || 0;
  const available = pickedLeft[slot] || 0;
  const take = Math.min(available, want);
  if (take > 0) {
    pickedLeft[slot] = Math.round((available - take) * 1000) / 1000;
  }
  row.pending_process_qty = Math.max(
    0,
    Math.round((want - take) * 1000) / 1000
  );
  row.line_status =
    row.pending_process_qty <= 0
      ? "Completed"
      : take > 0
        ? "In Progress"
        : "Open";
}

// Records the reversal decided to shrink or drop. Everything else passes through
// untouched, including other plans' records on a shared Picking. A record reduced
// to zero is simply not emitted, which the platform soft-deletes -- the row
// survives in the table for audit rather than being destroyed.
const storedRecords =
  (existingTOData && existingTOData.table_picking_records) || [];
const recordAdjustments = {};
for (const a of reconcilePlan.recordAdjustments || []) {
  recordAdjustments[String(a.id)] = a;
}

const mergedRecords = [];
for (const rec of storedRecords) {
  const adj = recordAdjustments[String(rec.id || "")];
  if (!adj) {
    mergedRecords.push(rec);
    continue;
  }
  if (Number(adj.drop) === 1) continue;
  mergedRecords.push({
    ...rec,
    store_out_qty: Math.max(
      0,
      Math.round((parseFloat(adj.store_out_qty) || 0) * 1000) / 1000
    ),
    picked_qty_alt: Math.max(
      0,
      Math.round((parseFloat(adj.picked_qty_alt) || 0) * 1000) / 1000
    )
  });
}

tablePickingItems.splice(0, tablePickingItems.length, ...nestBundleRows(tablePickingItems));

// Get SO numbers for display
const soNOs = [...new Set(tablePickingItems.map((pi) => pi.so_no).filter(Boolean))];

// Build the transfer order data
const transferOrderData = {
  // On a create this is always "Created". On an update it is whatever the
  // reconcile decided, falling back to the Picking's current status -- writing a
  // flat "Created" here would silently demote a Picking that had moved on.
  to_status:
    reconcilePlan.targetPickingToStatus ||
    (existingTOData && existingTOData.to_status) ||
    "Created",
  to_id: 'issued',
  to_id_type: pickingNoType,
  plant_id: allData.plant_id,
  organization_id: organizationId,
  movement_type: "Picking",
  ref_doc_type: "Picking Plan",
  to_no: [ppId],
  so_no: soNOs.join(", "),
  customer_id: allData.customer_name,
  ref_doc: allData.to_ref_doc,
  assigned_to: allData.assigned_to,
  project_id: allData.project_id ?? "",
  table_picking_items: carriedRows.concat(tablePickingItems),
  table_picking_records: mergedRecords,
  is_deleted: 0,
};

// Notification data
let notificationData = null;
let removedUsers = [];
let addedUsers = [];

if (isUpdate === 1 && existingTO) {
  // Prepare for update
